"""YAML configuration helper for extracting service.port safely."""

import yaml


def service_port(config_text: str) -> int:
    """
    Parse a YAML configuration document and return the integer at service.port.

    Raises:
        ValueError: If the document's top level is not a mapping.
        KeyError: If service or port is missing.
    """
    data = yaml.safe_load(config_text)
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise ValueError("configuration must be a mapping at the top level")

    try:
        service = data["service"]
        port = service["port"]
    except KeyError:
        raise KeyError("service.port") from None

    return port

from __future__ import annotations

from collections.abc import Mapping

import yaml


def service_port(config_text: str) -> int:
    """
    Parse a YAML configuration document and return the integer at service.port.

    Raises:
        KeyError: if service or port is missing.
        ValueError: if the top-level document is not a mapping.
    """
    data = yaml.safe_load(config_text)

    if data is None:
        data = {}
    if not isinstance(data, Mapping):
        raise ValueError("top-level YAML document must be a mapping")

    try:
        service = data["service"]
        port = service["port"]
    except KeyError:
        raise
    except TypeError:
        raise KeyError("port")

    return port
